import type { ConversationStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface ConversationStatusEntry {
  label: string;
  variant: BadgeVariants;
}

// Key order defines the user-visible filter order (New, Processing, Completed, Failed, Discarded).
export const conversationStatusConfig: Record<ConversationStatus, ConversationStatusEntry> = {
  new: { label: 'New', variant: 'info' },
  processing: { label: 'Processing', variant: 'info' },
  completed: { label: 'Completed', variant: 'success' },
  failed: { label: 'Failed', variant: 'destructive' },
  discarded: { label: 'Discarded', variant: 'default' },
};

const defaultConversationStatus: ConversationStatusEntry = { label: '', variant: 'default' };

export function getConversationStatusBadge(status: ConversationStatus): ConversationStatusEntry {
  return (
    conversationStatusConfig[status] ?? { ...defaultConversationStatus, label: snakeCaseToCapitalizedCase(status) }
  );
}

export const conversationStatuses: SelectItem<ConversationStatus>[] = Object.entries(conversationStatusConfig).map(
  ([value, { label }]) => ({ value: value as ConversationStatus, name: label })
);
